NSMutableArray *capitalised = [NSMutableArray arrayWithCapacity:words.count];
for (NSString *w in words) {
    if (w.length > 0) {
        NSString *first  = [[w substringToIndex:1] uppercaseString];
        NSString *rest   = [w substringFromIndex:1];
        [capitalised addObject:[first stringByAppendingString:rest]];
